// Quantité adaptée au nombre de personnes (base 2), arrondie proprement.
export function scale(q, persons, u) {
  const v = q * persons / 2;
  if (u === 'pc' && v > 1) return Math.ceil(v - 0.01);
  if (v >= 10) return Math.round(v);
  if (v >= 1) return Math.round(v * 2) / 2;
  return Math.round(v * 10) / 10;
}
export const UNITS = { g: 'g', ml: 'ml', l: 'l', kg: 'kg', pc: '', cs: 'c. à s.', cc: 'c. à c.', 'pincée': 'pincée' };
export const qty = (ing, persons) => { const v = scale(ing.q, persons, ing.u); const u = UNITS[ing.u] ?? ing.u; return u ? `${v} ${u}` : `${v}`; };
